var t=`1370-cachapas`;var n=`world-1370`;var s=`VE`;var a=`south-america`;var o=4;var r=37;var h={en:`Cachapas`,ua:`Качапас`};var l={en:`Cachapas is a dish from Venezuela featuring fresh corn kernels, whole cow milk, chicken egg, queso fresco. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Качапас, страва кухні країни Венесуела з такими основними складниками: зерна свіжої кукурудзи, цільне коров'яче молоко, куряче яйце, кесо фреско. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:11,i:[[`fresh-corn-kernels`,820,`g`],[`whole-cow-milk`,230,`ml`],[`chicken-egg`,2,`pcs`],[`white-granulated-sugar`,40,`g`],[`table-salt`,5,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`canola-oil`,70,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:6,i:[[`queso-fresco`,230,`g`],[`mozzarella`,160,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`unsalted-butter`,40,`g`]]}];var u={slug:t,id:n,country:`VE`,region:a,servings:4,minutes:37,title:h,text:l,steps:g};export{s as country,u as default,n as id,r as minutes,a as region,o as servings,t as slug,g as steps,l as text,h as title};